import {AREAS,LETTERS,normalize,selectQuestions,evaluate,isCorrect,remainingSeconds,formatTime,questionStatus} from './core.mjs';
const $=(q,root=document)=>root.querySelector(q);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',bank:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h8M8 17h4"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v5l3 2M9 2h6M17 5l2-2"/>',chart:'<path d="M4 19h16M7 15v-4M12 15V5M17 15V8"/>',bookmark:'<path d="M6 4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v17l-6-4-6 4Z"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',left:'<path d="M19 12H5m5-5-5 5 5 5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',math:'<path d="M17 4H6l7 8-7 8h11"/>',book:'<path d="M12 6C8 3 4 4 2 5v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-3-1-7-2-10 1Zm0 0v14"/>',flask:'<path d="M9 3h6M10 3v7L4 20a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1l-6-10V3M7 15h10"/><path d="M9 18h.01M14 17h.01"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z"/>',language:'<path d="M3 5h12M9 3v2M6 5c0 7 6 10 6 10M13 5C12 11 7 15 3 16m11 5 4-10 4 10m-6-4h4"/>',check:'<path d="m5 12 4 4L19 6"/>',cross:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',flag:'<path d="M5 21V3h13l-3 4 3 4H5"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l4 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10s-8-5-8-10V6Z"/><path d="m8 11 3 3 5-5"/>'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.bank}</svg>`;
const areaBy=id=>AREAS.find(a=>a.id===id);
const dateFmt=(date,opts={day:'numeric',month:'short'})=>new Intl.DateTimeFormat('es-CO',opts).format(new Date(date));
const storageKey='punto-progress-v1';
let state={version:1,bookmarks:[],attempts:{},history:[],session:null,reports:[]};
let storageOK=true,bank,questions=[],catalog=[],route='inicio';
let filter={search:'',area:'all',status:'all',page:1};
let sourceFilter={search:'',period:'all',page:1};
let savedBankOnly=false,toastTimeout,examConfig={area:'all',count:20,minutes:40};
let lastResultId=null,reviewFilter='all',lastFocused=null;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&saved.version===1){state={...state,...saved};if(!Array.isArray(state.bookmarks))state.bookmarks=[];if(!Array.isArray(state.history))state.history=[];if(!state.attempts||typeof state.attempts!=='object')state.attempts={};if(!Array.isArray(state.reports))state.reports=[];}}catch{storageOK=false;}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));return true;}catch{if(storageOK){storageOK=false;toast('No se pudo guardar el progreso. Puedes exportar tus datos en Mi progreso.');}return false;}}
function toast(message){clearTimeout(toastTimeout);const el=$('#toast');el.textContent=message;el.classList.add('visible');toastTimeout=setTimeout(()=>el.classList.remove('visible'),3600);}
const btn=(text,action,variant='primary',extra='',ico='arrow')=>`<button class="btn btn-${variant}" data-action="${action}" ${extra}>${esc(text)}${ico?icon(ico,14):''}</button>`;
const areaStyle=a=>`--area:${a.color};--area-light:${a.light}`;
function navigate(hash){if(location.hash===`#${hash}`)render();else location.hash=hash;}
function getQuestion(id){return questions.find(q=>q.id===id);}
function sessionQuestions(s=state.session){return s?s.ids.map(getQuestion).filter(Boolean):[];}
function validSession(s){return s&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.every(id=>getQuestion(id))&&['learn','exam'].includes(s.mode)&&Number.isFinite(s.startedAt)&&(s.mode!=='exam'||Number.isFinite(s.deadline))&&s.answers&&s.checked;}
function sessionDoneCount(){return state.session?Object.keys(state.session.answers).length:0;}
function nav(){const items=[['inicio','home','Mi espacio'],['banco','bank','Banco de preguntas'],['simulacro','timer','Simulacro'],['progreso','chart','Mi progreso'],['guardadas','bookmark','Guardadas'],['fuentes','folder','Biblioteca']];$('#navigation').innerHTML=items.map(([id,ico,label])=>`<a class="nav-link ${route===id||(route==='practica'&&id==='banco')||(route==='resultados'&&id==='progreso')?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''} title="${label}">${icon(ico,19)}<span>${label}</span>${id==='banco'?'<span class="nav-tag">60</span>':''}</a>`).join('');$('#crumb').textContent=({inicio:'Mi espacio',banco:'Banco de preguntas',guardadas:'Guardadas',simulacro:'Simulacro',practica:'En práctica',progreso:'Mi progreso',resultados:'Resultados',fuentes:'Biblioteca'})[route]||'Mi espacio';}
function heading(eyebrow,title,description,aside=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="tiny-dot"></span>${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${aside}</div>`;}
function sourceInline(){return `<div class="source-inline">${icon('info',13)}<span>Banco histórico 2003–2010. Las preguntas interactivas corresponden a 2005-1 y conservan su clave de origen. Las áreas son una organización de estudio. <a href="#fuentes">Conoce las fuentes ↗</a></span></div>`;}
function continueBanner(){let s=state.session;if(!s)return '';return `<div class="continue-banner"><div><h3>Dejaste una ${s.mode==='exam'?'simulación':'práctica'} en camino.</h3><p>${sessionDoneCount()} de ${s.ids.length} preguntas respondidas${s.mode==='exam'?' · El tiempo sigue corriendo':''}.</p></div>${btn('Continuar','resume','soft')}</div>`;}
function heroArt(){return `<svg viewBox="0 0 340 290" fill="none" aria-hidden="true"><circle cx="178" cy="146" r="112" stroke="#d7e2f7"/><circle cx="178" cy="146" r="84" stroke="#dce6f9" stroke-dasharray="3 7"/><circle cx="276" cy="79" r="7" fill="#c4d3ee"/><circle cx="91" cy="225" r="4" fill="#bed284"/><path d="M88 200q67 40 177-42" stroke="#ccdaf1" stroke-width="2" stroke-dasharray="5 6"/><g transform="rotate(-8 180 140)"><rect x="105" y="69" width="143" height="169" rx="14" fill="#cbd9ef"/><rect x="98" y="61" width="143" height="169" rx="14" fill="#fff" stroke="#d6e1f3"/><rect x="115" y="82" width="61" height="5" rx="2.5" fill="#cad8ee"/><rect x="115" y="93" width="94" height="4" rx="2" fill="#e6ecf6"/><rect x="115" y="119" width="20" height="20" rx="6" fill="#ecf1fc"/><path d="m120 128 4 4 7-7" stroke="#7595c5" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M147 125h60m-60 8h40" stroke="#d9e3f3" stroke-width="4" stroke-linecap="round"/><rect x="115" y="151" width="20" height="20" rx="6" fill="#ecf1fc"/><path d="m120 160 4 4 7-7" stroke="#7595c5" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M147 157h46m-46 8h60" stroke="#d9e3f3" stroke-width="4" stroke-linecap="round"/><rect x="115" y="183" width="20" height="20" rx="6" fill="#f0f4fa"/><path d="M147 189h56m-56 8h35" stroke="#e2e9f5" stroke-width="4" stroke-linecap="round"/></g><circle cx="246" cy="183" r="37" fill="#9ab3de"/><circle cx="246" cy="179" r="37" fill="#325fb3"/><path d="m229 179 11 11 22-23" stroke="white" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><g transform="rotate(17 92 85)"><rect x="65" y="59" width="51" height="51" rx="13" fill="#e2edc3"/><path d="m90 71 3 9 10 3-10 3-3 10-3-10-10-3 10-3Z" fill="#94aa5f"/></g><path d="m273 112 3 7 8 3-8 3-3 8-3-8-7-3 7-3Z" fill="#a7bfdf"/></svg>`;}
function home(){let answered=Object.keys(state.attempts).filter(id=>state.attempts[id]?.length).length;let allAttempts=Object.values(state.attempts).flat();let rate=allAttempts.length?Math.round(100*allAttempts.filter(x=>x.correct).length/allAttempts.length):null;
 return `${heading('TU PRÓXIMO GRAN PASO','Cada pregunta te acerca.','Entrena a tu ritmo. Descubre lo que sabes y lo que puedes mejorar.',`<span class="outline-label">${icon('shield',13)} Sin registro · A tu ritmo</span>`)}${continueBanner()}<section class="hero"><div class="hero-body"><div class="eyebrow">MENOS NERVIOS. MÁS CONFIANZA.</div><h2>Tu futuro empieza<br>con una pregunta.</h2><p>Practica con preguntas históricas del ICFES.<br>Entiende tus respuestas y encuentra tu propio ritmo.</p>${btn('Comenzar a practicar','quick')}<span class="hero-fine">10 preguntas para dar el primer paso</span></div><div class="hero-art">${heroArt()}</div></section><div class="stats-row"><div class="stat"><span class="stat-icon">${icon('bank')}</span><div><div class="stat-value">60</div><div class="stat-label">preguntas para entrenar</div></div></div><div class="stat"><span class="stat-icon">${icon('target')}</span><div><div class="stat-value">${answered}<span style="font-size:12px;color:#a1aec1;font-weight:400"> / 60</span></div><div class="stat-label">preguntas exploradas por ti</div></div></div><div class="stat"><span class="stat-icon">${icon('chart')}</span><div><div class="stat-value">${rate===null?'—':rate+'<span style="font-size:14px">%</span>'}</div><div class="stat-label">${rate===null?'tu avance comienza hoy':'aciertos en tus respuestas'}</div></div></div></div><section><div class="section-heading"><div><h2>Una materia. Un nuevo avance.</h2><p>Elige dónde quieres poner el foco hoy.</p></div><a class="text-link" href="#banco">Explorar el banco ${icon('arrow',13)}</a></div><div class="area-grid">${AREAS.map(a=>`<button class="area-card" data-action="area-practice" data-area="${a.id}" style="${areaStyle(a)}"><span class="area-icon">${icon(a.icon,20)}</span><h3>${a.name}</h3><div class="area-desc">${a.description}</div><div class="area-card-bottom"><span>${questions.filter(q=>q.area===a.id).length} preguntas</span>${icon('arrow',14)}</div></button>`).join('')}</div></section><div class="bottom-grid"><section class="panel"><div class="panel-title"><h3>Tu actividad reciente</h3><a class="text-link" href="#progreso">Ver todo ${icon('arrow',12)}</a></div>${state.history.length?state.history.slice(0,2).map(historyItem).join(''):`<div class="empty-recent"><div class="empty-icon">${icon('history',23)}</div><div><h4>Todo gran avance tiene un comienzo.</h4><p>Tu primera sesión aparecerá aquí.<br>¿Qué tal si empezamos con 10 preguntas?</p></div></div>`}</section><section class="panel routine"><div class="eyebrow">UN HÁBITO QUE SUMA</div><h3>Empieza pequeño.<br>Avanza en serio.</h3>${btn('Mi sesión de 10 preguntas','quick','quiet')}</section></div>${sourceInline()}`;
}
function matchingQuestions(){let query=normalize(filter.search);return questions.filter(q=>(!savedBankOnly||state.bookmarks.includes(q.id))&&(filter.area==='all'||q.area===filter.area)&&(!query||normalize(`${q.title} ${q.prompt} ${q.topic} ${q.discipline} ${q.number}`).includes(query))&&(filter.status==='all'||(filter.status==='new'&&questionStatus(q,state)==='new')||(filter.status==='done'&&questionStatus(q,state)!=='new')||(filter.status==='review'&&questionStatus(q,state)==='review')||(filter.status==='saved'&&state.bookmarks.includes(q.id))));}
function areaSelect(id,selected='all',all='Todas las áreas'){return `<select id="${id}" aria-label="Filtrar por área"><option value="all">${all}</option>${AREAS.map(a=>`<option value="${a.id}" ${selected===a.id?'selected':''}>${a.name}</option>`).join('')}</select>`;}
function questionRow(q){let a=areaBy(q.area),status=questionStatus(q,state);return `<article class="question-row" style="${areaStyle(a)}"><div class="area-icon">${icon(a.icon,19)}</div><div class="question-row-main"><button data-action="preview-question" data-id="${q.id}"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p></button><div class="row-tags"><span>${a.short}</span><span class="divider">·</span><span>2005-1 · N.º ${q.number}</span><span class="pill ${status==='correct'?'success':status==='review'?'warn':''}">${status==='correct'?'Respondida ✓':status==='review'?'Para repasar':'Sin resolver'}</span></div></div><button class="icon-btn ${state.bookmarks.includes(q.id)?'saved':''}" data-action="bookmark" data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Quitar de guardadas':'Guardar pregunta'}: ${esc(q.title)}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('bookmark',17)}</button><button class="icon-btn row-open" data-action="preview-question" data-id="${q.id}" aria-label="Abrir ${esc(q.title)}">${icon('chevron',17)}</button></article>`;}
function bankView(){savedBankOnly=route==='guardadas';return `${heading(savedBankOnly?'TU COLECCIÓN':'PRACTICAR PARA COMPRENDER',savedBankOnly?'Preguntas que quieres volver a ver.':'Un banco de posibilidades.',savedBankOnly?'Guarda lo que te reta. Vuelve cuando quieras.':'60 preguntas digitalizadas, con clave de origen y orientación para aprender.')}<div class="tool-row"><div class="search-field">${icon('search',17)}<input id="bank-search" type="search" placeholder="Busca un tema, una pregunta o una palabra…" value="${esc(filter.search)}" aria-label="Buscar preguntas" autocomplete="off"></div>${areaSelect('bank-area',filter.area)}${btn('Practicar esta selección','filtered-practice')}</div><div class="chips" aria-label="Estado de las preguntas">${[['all','Todas'],['new','Sin resolver'],['done','Respondidas'],['review','Para repasar'],...(!savedBankOnly?[['saved','Guardadas']]:[])].map(([id,label])=>`<button class="chip ${filter.status===id?'active':''}" data-action="filter-status" data-status="${id}" aria-pressed="${filter.status===id}">${label}</button>`).join('')}</div><div id="bank-results">${bankResults()}</div>${sourceInline()}`;}
function bankResults(){let items=matchingQuestions(),pages=Math.max(1,Math.ceil(items.length/12));filter.page=Math.min(filter.page,pages);return `<div class="bank-meta"><span>${items.length} ${items.length===1?'pregunta disponible':'preguntas disponibles'}</span><span>Organizadas para tu práctica</span></div>${items.length?`<div class="question-list">${items.slice((filter.page-1)*12,filter.page*12).map(questionRow).join('')}</div>${pagination(filter.page,pages,'bank')}`:`<div class="empty-state"><div class="empty-icon">${icon(savedBankOnly?'bookmark':'search',26)}</div><h2>${savedBankOnly&&!state.bookmarks.length?'Tu colección empieza aquí.':'No encontramos preguntas con esos filtros.'}</h2><p>${savedBankOnly&&!state.bookmarks.length?'Usa el marcador en cualquier pregunta para guardarla y revisarla después.':'Prueba otra palabra o cambia el área para seguir explorando.'}</p>${btn(savedBankOnly?'Explorar preguntas':'Limpiar filtros',savedBankOnly?'go-bank':'reset-filters','soft')}</div>`}`;}
function pagination(page,pages,type){if(pages<2)return '';return `<div class="pagination"><button class="icon-btn" data-action="${type}-page" data-page="${page-1}" ${page===1?'disabled':''} aria-label="Página anterior">${icon('left',16)}</button><span>Página ${page} de ${pages}</span><button class="icon-btn" data-action="${type}-page" data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Página siguiente">${icon('arrow',16)}</button></div>`;}
function examView(){const max=questions.filter(q=>examConfig.area==='all'||q.area===examConfig.area).length;return `${heading('ENTRENA TU CONCENTRACIÓN','Dale un ensayo a ese gran día.','Una sesión con tiempo para poner a prueba tu estrategia.')}${continueBanner()}<div class="config-grid"><section class="panel config-panel"><h2>Tu simulación, a tu medida.</h2><p>Elige las preguntas y el tiempo. Las respuestas se revisan al terminar.</p><div class="form-group"><label for="exam-area">¿Qué quieres practicar?</label>${areaSelect('exam-area',examConfig.area,'Combinar las cinco áreas')}</div><div class="form-group"><fieldset><legend>Número de preguntas</legend><div class="choice-grid">${[10,20,40,60].map(n=>`<label class="choice"><input type="radio" name="exam-count" value="${n}" ${examConfig.count===n?'checked':''} ${n>max?'disabled':''}>${n}</label>`).join('')}</div></fieldset></div><div class="form-group"><label for="exam-minutes">Tiempo disponible</label><select id="exam-minutes">${[10,15,20,30,40,60,90,120].map(m=>`<option value="${m}" ${examConfig.minutes===m?'selected':''}>${m} minutos</option>`).join('')}</select></div><div class="config-note">${icon('info',14)} El reloj sigue corriendo si cambias de pantalla o cierras la pestaña. Al finalizar el tiempo, se registran las respuestas que hayas elegido. Puedes dejar preguntas sin responder.</div>${btn('Comenzar simulación','start-exam')}<p class="small muted" style="margin-top:15px;font-size:10px">El resultado es un porcentaje de práctica. No equivale a un puntaje oficial del ICFES.</p></section><aside class="panel config-panel"><span class="pill blue">ANTES DE EMPEZAR</span><h2 style="margin-top:18px">Haz espacio para concentrarte.</h2><p>Un entorno tranquilo hace la diferencia.</p><div class="feature-list">${[['Lee antes de elegir.','Comprende la situación, los datos y lo que realmente te están preguntando.'],['Administra tu tiempo.','Puedes pasar a otra pregunta y regresar antes de entregar.'],['Aprende de la revisión.','Al finalizar, revisa la clave y la explicación de apoyo de cada respuesta.']].map(([a,b],i)=>`<div class="feature-item"><span class="num">${i+1}</span><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div><div class="config-note" style="margin-top:28px">Material histórico de 2005. Esta simulación combina áreas para estudiar; su distribución y duración no reproducen la estructura del examen actual.</div></aside></div>`;}
function showModal(title,body,{wide=false}={}){let modal=$('#modal');lastFocused=document.activeElement;if(modal.open)modal.close();modal.classList.toggle('modal-wide',wide);modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar ventana">${icon('cross',19)}</button></div><div class="modal-body">${body}</div>`;modal.showModal();}
function closeModal(){const m=$('#modal');if(m.open)m.close();if(lastFocused?.isConnected)lastFocused.focus();}
function practiceConfig(area='all',ids=null){const available=questions.filter(q=>(area==='all'||q.area===area)&&(!ids||ids.includes(q.id))).length;if(!available){toast('No hay preguntas en esta selección. Cambia los filtros para practicar.');return;}const a=areaBy(area);showModal(a?a.name:'Tu próxima práctica',`<p>${a?a.topics:'Una selección equilibrada de las cinco áreas.'} Revisa cada respuesta y aprende a tu ritmo.</p><form id="practice-form"><input type="hidden" name="area" value="${area}"><input type="hidden" name="ids" value="${esc(ids?JSON.stringify(ids):'')}"><div class="form-group"><label for="practice-count">¿Cuántas preguntas quieres resolver?</label><select id="practice-count" name="count">${[5,10,20,40,60].filter(n=>n<available).concat(available).filter((n,i,arr)=>arr.indexOf(n)===i).sort((a,b)=>a-b).map(n=>`<option value="${n}" ${n===Math.min(10,available)?'selected':''}>${n} preguntas${n===available?' · Todas las disponibles':''}</option>`).join('')}</select></div><div class="config-note">${icon('spark',14)} Sin límite de tiempo. Puedes guardar preguntas, consultar la explicación después de responder y continuar tu sesión más tarde.</div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-action="close-modal">Volver</button><button class="btn btn-primary" type="submit">Empezar práctica ${icon('arrow',14)}</button></div></form>`);}
function requestStart(config){if(state.session){showModal('Ya tienes una sesión en camino.',`<p>Llevas ${sessionDoneCount()} de ${state.session.ids.length} preguntas respondidas. Puedes continuarla o terminarla y empezar una nueva.</p><div class="modal-actions">${btn('Continuar mi sesión','resume','secondary','',null)}${btn('Terminar y empezar otra','replace-session','primary','',null)}</div>`);pendingConfig=config;return;}startSession(config);}
let pendingConfig=null;
function startSession({area='all',count=10,mode='learn',minutes=20,ids=null}){let picked=selectQuestions(questions,{area,count,ids});if(!picked.length){toast('No hay preguntas disponibles.');return;}const now=Date.now();state.session={id:crypto.randomUUID(),ids:picked.map(q=>q.id),mode,area,answers:{},checked:{},index:0,startedAt:now,deadline:mode==='exam'?now+minutes*60000:null,minutes};persist();closeModal();navigate('practica');}
function contextMarkup(q){let out='';if(q.context)out+=`<details class="context" open><summary>Lee el contexto · ${esc(q.context.title)}</summary><div class="context-content"><h3>${esc(q.context.title)}</h3><p class="${q.context.verse?'verse':''}" ${q.area==='ingles'?'lang="en"':''}>${esc(q.context.body)}</p>${q.context.citation?`<p class="citation">${esc(q.context.citation)}</p>`:''}</div></details>`;if(q.table)out+=`<div style="overflow-x:auto"><table class="data-table"><caption class="sr-only">Datos para ${esc(q.title)}</caption><thead><tr>${q.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${q.table.rows.map(r=>`<tr>${r.map((c,i)=>i===0?`<th scope="row" style="font-weight:450;background:#fafbfd">${esc(c)}</th>`:`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;if(q.image)out+=`<img class="source-image" src="${q.image.url}" alt="${esc(q.image.alt)}" width="520" height="260">`;return out;}
function sourceMarkup(q){return `<div class="question-source"><span>ICFES · ${esc(q.discipline)} · 2005-1 · N.º ${q.number}<br>Adaptación de lectura en pantalla.</span><a href="${q.source}#page=${q.page}" target="_blank" rel="noopener">Ver cuadernillo ${icon('external',11)}</a></div>`;}
function feedbackMarkup(q,answer){let ok=isCorrect(q,answer);return `<div class="feedback ${ok?'':'wrong'}" role="status"><h3>${icon(ok?'check':'info',17)}${ok?'Bien pensado. Sigue así.':answer?'Una oportunidad para entenderlo mejor.':'Una pregunta para volver a explorar.'}</h3><p><strong>${q.answers.length>1?'Alternativas aceptadas':'Respuesta de la clave'}: ${q.answers.join(' y ')}.</strong> ${esc(q.explanation)}</p><div class="feedback-source">Orientación didáctica de Punto · Clave: respuestas.xls, ${esc(q.keySheet)}, fila ${q.keyRow}. ${q.answers.length>1?'El ítem original acepta cualquiera de las dos alternativas.':''}</div></div>`;}
function answersMarkup(q,answer,checked,{interactive=true}={}){return `<fieldset class="answer-group"><legend class="sr-only">Opciones de respuesta</legend>${q.options.map((o,i)=>{const letter=LETTERS[i];const correct=checked&&q.answers.includes(letter);const wrong=checked&&letter===answer&&!correct;return `<button type="button" class="answer ${answer===letter?'selected':''} ${correct?'correct':''} ${wrong?'wrong':''}" ${interactive?'data-action="answer"':''} data-letter="${letter}" ${checked||!interactive?'disabled':''} ${interactive?`aria-pressed="${answer===letter}"`:''}><span class="answer-letter">${letter}</span><span ${q.area==='ingles'?'lang="en"':''}>${esc(o)}</span>${correct?icon('check',15):wrong?icon('cross',15):''}</button>`;}).join('')}</fieldset>`;}
function practiceView(){if(!validSession(state.session)){state.session=null;persist();return `<div class="empty-state"><div class="empty-icon">${icon('bank',25)}</div><h2>Tu siguiente práctica te espera.</h2><p>Elige una selección de preguntas para comenzar.</p>${btn('Elegir preguntas','go-bank')}</div>`;}let s=state.session;s.index=Math.max(0,Math.min(Number(s.index)||0,s.ids.length-1));let q=getQuestion(s.ids[s.index]),a=areaBy(q.area),answer=s.answers[q.id],checked=s.mode==='learn'&&s.checked[q.id];let percent=100*Object.keys(s.answers).length/s.ids.length;
return `<div class="practice-wrap"><div class="practice-top"><button class="back-link" data-action="session-home">${icon('left',14)} Volver a mi espacio</button><div class="session-info"><span class="pill blue exam-mode">${s.mode==='exam'?'Simulación con tiempo':'Práctica guiada'}</span><span class="timer" id="session-timer" aria-label="${s.mode==='exam'?'Tiempo restante':'Tiempo transcurrido'}">${icon('clock',15)}<span>${s.mode==='exam'?formatTime(remainingSeconds(s)):formatTime((Date.now()-s.startedAt)/1000)}</span></span></div></div><div class="progress-track" role="progressbar" aria-label="Preguntas respondidas" aria-valuenow="${Object.keys(s.answers).length}" aria-valuemin="0" aria-valuemax="${s.ids.length}"><i style="width:${percent}%"></i></div><div class="practice-layout"><div><article class="question-card" style="${areaStyle(a)}"><div class="question-label"><span>Pregunta ${s.index+1} <span class="muted">de ${s.ids.length}</span></span><div style="display:flex;gap:5px"><button class="icon-btn ${state.bookmarks.includes(q.id)?'saved':''}" data-action="bookmark" data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Quitar de guardadas':'Guardar pregunta'}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('bookmark',17)}</button><button class="icon-btn" data-action="report" data-id="${q.id}" aria-label="Anotar un problema en esta pregunta">${icon('flag',16)}</button></div></div><div class="question-kicker"><span class="pill" style="color:${a.color};background:${a.light}">${icon(a.icon,12)} ${a.short}</span><span class="pill">${esc(q.discipline)}</span>${q.answers.length>1?'<span class="pill warn">Ítem histórico · Dos alternativas válidas</span>':''}</div><h1>${esc(q.title)}</h1>${contextMarkup(q)}<p class="prompt" ${q.area==='ingles'?'lang="en"':''}>${esc(q.prompt)}</p>${answersMarkup(q,answer,checked)}${checked?feedbackMarkup(q,answer):''}${sourceMarkup(q)}</article><div class="question-actions">${btn('Anterior','prev-question','secondary',s.index===0?'disabled':'','left')}<div class="question-actions-right">${!checked&&s.mode==='learn'?btn('Comprobar respuesta','check-answer','primary',!answer?'disabled':'','check'):''}${(checked||s.mode==='exam')&&s.index<s.ids.length-1?btn('Siguiente','next-question'):!checked&&s.mode==='learn'?btn('Saltar','next-question','quiet','',null):btn('Terminar sesión','finish-session')}</div></div><p class="session-note">${s.mode==='learn'?'Atajo: teclas 1, 2, 3 y 4 para elegir una respuesta. Compruébala antes de ver la explicación.':'Puedes cambiar tus respuestas y regresar a cualquier pregunta antes de entregar. El reloj sigue corriendo.'}</p></div><aside class="practice-side"><h3>Tu recorrido</h3><p>${Object.keys(s.answers).length} de ${s.ids.length} respondidas</p><div class="q-grid">${s.ids.map((id,i)=>{const item=getQuestion(id);let cl=s.answers[id]?'answered':'';if(s.mode==='learn'&&s.checked[id])cl=isCorrect(item,s.answers[id])?'good':'bad';return `<button class="q-dot ${cl} ${s.index===i?'current':''} ${state.bookmarks.includes(id)?'flagged':''}" data-action="goto-question" data-index="${i}" aria-label="Pregunta ${i+1}${s.answers[id]?', respondida':''}" ${s.index===i?'aria-current="step"':''}>${i+1}</button>`;}).join('')}</div><div class="grid-legend">${s.mode==='learn'?'Verde: correcta · Ámbar: repasar':'Azul: respondida'}<br>Punto: guardada para después</div>${btn('Terminar sesión','finish-session','secondary','',null)}</aside></div></div>`;}
function recordAttempt(q,answer,sessionId){if(!LETTERS.includes(answer))return;let entries=state.attempts[q.id]||[];if(entries.some(a=>a.sessionId===sessionId))return;state.attempts[q.id]=[...entries,{answer,correct:isCorrect(q,answer),at:Date.now(),sessionId}].slice(-100);}
function checkAnswer(){let s=state.session;if(!s||s.mode!=='learn')return;const q=getQuestion(s.ids[s.index]),a=s.answers[q.id];if(!a||s.checked[q.id])return;s.checked[q.id]=true;recordAttempt(q,a,s.id);persist();render(false);$('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function requestFinish(){let s=state.session;if(!s)return;let unanswered=s.ids.filter(id=>!s.answers[id]).length,unchecked=s.mode==='learn'?s.ids.filter(id=>s.answers[id]&&!s.checked[id]).length:0;showModal('¿Terminamos esta sesión?',`<p>${unanswered?`Quedan ${unanswered} preguntas sin responder. Contarán como omitidas en el resultado.`:'Ya elegiste una respuesta en todas las preguntas.'}${unchecked?` Tus ${unchecked} respuestas pendientes de comprobar también se evaluarán al terminar.`:''}</p><div class="modal-actions">${btn('Seguir practicando','close-modal','secondary','',null)}${btn(s.mode==='exam'?'Entregar respuestas':'Ver mis resultados','confirm-finish','primary','',null)}</div>`);}
function finishSession(expired=false){let s=state.session;if(!s)return;const qs=sessionQuestions(s);for(const q of qs)recordAttempt(q,s.answers[q.id],s.id);const duration=Math.max(0,Math.round(((expired?s.deadline:Date.now())-s.startedAt)/1000));const result={id:s.id,ids:s.ids,answers:{...s.answers},mode:s.mode,area:s.area,startedAt:s.startedAt,finishedAt:expired?s.deadline:Date.now(),duration,expired,summary:evaluate(qs,s.answers)};state.history=[result,...state.history.filter(h=>h.id!==s.id)].slice(0,200);lastResultId=result.id;state.session=null;persist();closeModal();reviewFilter='all';navigate('resultados');if(expired)toast('El tiempo terminó. Tus respuestas quedaron registradas.');}
function getResult(){return state.history.find(h=>h.id===lastResultId)||state.history[0];}
function reviewCard(q,r){const answer=r.answers[q.id],ok=isCorrect(q,answer);return `<details class="panel review-card" style="padding:0"><summary><span class="review-status ${ok?'':answer?'bad':'empty'}">${icon(ok?'check':answer?'cross':'info',12)}</span><span class="review-title">${esc(q.title)}</span><span class="pill ${ok?'success':answer?'warn':''}">${ok?'Correcta':answer?'Para repasar':'Omitida'}</span>${icon('chevron',13)}</summary><div class="review-content">${contextMarkup(q)}<p class="prompt" ${q.area==='ingles'?'lang="en"':''}>${esc(q.prompt)}</p>${answersMarkup(q,answer,true,{interactive:false})}${feedbackMarkup(q,answer)}${sourceMarkup(q)}<div style="display:flex;justify-content:flex-end;margin-top:12px">${btn(state.bookmarks.includes(q.id)?'Quitar de guardadas':'Guardar para repasar','bookmark','quiet',`data-id="${q.id}"`,'bookmark')}</div></div></details>`;}
function resultView(){let r=getResult();if(!r)return `<div class="empty-state"><h2>Tu primer resultado está por llegar.</h2><p>Completa una sesión para descubrir qué sabes y dónde puedes avanzar.</p>${btn('Empezar práctica','quick')}</div>`;let sum=r.summary||evaluate(r.ids.map(getQuestion).filter(Boolean),r.answers);let review=r.ids.map(getQuestion).filter(Boolean).filter(q=>reviewFilter==='all'||!isCorrect(q,r.answers[q.id]));let perfect=sum.correct===sum.total;return `${heading('CADA INTENTO CUENTA','Así fue tu recorrido.',`${r.mode==='exam'?'Simulación':'Práctica guiada'} · ${dateFmt(r.finishedAt,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})}`)}<section class="result-hero"><div class="score-ring" style="--score:${sum.percentage}"><div><strong>${sum.percentage}%</strong><span>DE ACIERTOS</span></div></div><div><h2>${perfect?'Un gran paso. Sigue construyendo.':'Tu siguiente avance empieza aquí.'}</h2><p>${perfect?'Resolviste correctamente todas las preguntas de esta sesión. Vuelve al banco para ampliar tu práctica.':'Ya sabes qué revisar. Vuelve a tus respuestas, entiende el porqué y dale una nueva oportunidad a lo que te retó.'}</p><div class="result-meta"><span>${sum.correct} correctas</span><span>${sum.incorrect} para repasar</span><span>${sum.omitted} omitidas</span><span>${formatTime(r.duration)} transcurridos</span></div></div></section>${r.expired?'<div class="config-note">Se agotó el tiempo de la simulación. Se evaluaron las respuestas guardadas antes del cierre.</div>':''}<div class="result-tools">${sum.total-sum.correct?btn('Practicar mis errores','retry-errors','primary','', 'history'):btn('Una nueva práctica','quick')}${btn('Exportar resultado','export-result','secondary','','download')}${btn('Ver mi progreso','go-progress','secondary','','chart')}</div><div class="section-heading" style="margin-top:30px"><div><h2>Entender también es avanzar.</h2><p>Abre cada pregunta para consultar tu respuesta y la clave.</p></div></div><div class="chips"><button class="chip ${reviewFilter==='all'?'active':''}" data-action="review-filter" data-filter="all" aria-pressed="${reviewFilter==='all'}">Todas (${sum.total})</button><button class="chip ${reviewFilter==='errors'?'active':''}" data-action="review-filter" data-filter="errors" aria-pressed="${reviewFilter==='errors'}">Para repasar (${sum.total-sum.correct})</button></div>${review.length?review.map(q=>reviewCard(q,r)).join(''):'<div class="empty-state"><h2>Esta vez, todo estuvo en su punto.</h2><p>No hay respuestas pendientes de repaso en esta sesión.</p></div>'}<p class="export-note">Porcentaje sobre todas las preguntas de la sesión, incluidas las omitidas. Es un indicador de práctica; no es un puntaje Saber 11 ni una predicción de resultados.</p>`;}
function historyItem(r){let s=r.summary||evaluate(r.ids.map(getQuestion).filter(Boolean),r.answers);return `<div class="history-item"><div><button data-action="open-result" data-id="${r.id}" style="padding:0;text-align:left"><h3>${r.mode==='exam'?'Simulación':'Práctica guiada'} · ${r.area==='all'?'Varias áreas':areaBy(r.area)?.short||'Selección'}</h3></button><p>${dateFmt(r.finishedAt)} · ${s.total} preguntas · ${formatTime(r.duration)}</p></div><button class="history-score" data-action="open-result" data-id="${r.id}" aria-label="Ver resultado: ${s.percentage} por ciento">${s.percentage}%</button></div>`;}
function progressView(){let all=Object.values(state.attempts).flat(),count=Object.values(state.attempts).filter(x=>x.length).length,correct=all.filter(x=>x.correct).length;let pending=questions.filter(q=>questionStatus(q,state)==='review').length;return `${heading('LOS PEQUEÑOS PASOS SE NOTAN','Tu avance, en perspectiva.','Cada sesión deja una pista sobre lo que puedes aprender después.',btn('Exportar progreso','export-progress','secondary','','download'))}<div class="progress-overview"><div class="progress-card"><strong>${count}<span class="muted" style="font-size:15px"> / 60</span></strong><p>Preguntas distintas exploradas</p></div><div class="progress-card"><strong>${state.history.length}</strong><p>Sesiones terminadas</p></div><div class="progress-card"><strong>${all.length?Math.round(100*correct/all.length)+'%':'—'}</strong><p>Aciertos en ${all.length} respuestas registradas</p></div></div>${continueBanner()}<div class="progress-layout"><section class="panel"><div class="panel-title"><h3>Tu recorrido por área</h3><span>Última respuesta por pregunta</span></div>${AREAS.map(a=>{let list=questions.filter(q=>q.area===a.id),done=list.filter(q=>questionStatus(q,state)!=='new'),good=done.filter(q=>questionStatus(q,state)==='correct');return `<div class="result-area" style="${areaStyle(a)}"><span>${a.short}</span><div class="bar"><i style="width:${100*good.length/list.length}%"></i></div><b>${good.length}/${list.length}</b></div><p style="font-size:9px;margin:5px 0 0 111px;color:#9aa8ba">${done.length} exploradas · ${list.length-done.length} por descubrir</p>`;}).join('')}<p class="export-note">La barra muestra preguntas cuya última respuesta fue correcta, sobre el total del área.</p>${pending?`<div class="config-note">Tienes ${pending} preguntas para repasar. ${btn('Volver a intentarlo','practice-pending','quiet','','history')}</div>`:''}</section><section class="panel"><div class="panel-title"><h3>Historial de sesiones</h3><span>${state.history.length} sesiones</span></div>${state.history.length?state.history.slice(0,12).map(historyItem).join(''):`<div class="empty-recent"><span class="empty-icon">${icon('history',23)}</span><div><h4>Aún no has terminado una sesión.</h4><p>Tu primera práctica es el punto de partida.</p></div></div>${btn('Comenzar','quick','quiet')}`}</section></div><div class="method-note"><h3>Tu espacio es tuyo.</h3><p>Las respuestas, sesiones y preguntas guardadas se conservan en este navegador. Si borras sus datos o cambias de equipo, no se sincronizan automáticamente. Exporta tu progreso para conservar una copia e impórtala en otro navegador.</p><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:13px">${btn('Importar progreso','import-progress','secondary','','download')}${btn('Borrar mis datos','reset-data','quiet','',null)}</div><input type="file" id="progress-file" accept="application/json,.json" hidden></div>`;}
function sourcesView(){let periods=[...new Set(catalog.map(p=>p.period))];return `${heading('CONOCE DE DÓNDE VIENE CADA PREGUNTA','El origen también importa.','106 cuadernillos originales para consultar, explorar y seguir aprendiendo.')}<div class="source-banner">${icon('info',25)}<div><h3>Una colección histórica, una práctica consciente.</h3><p>El archivo aportado contiene material de 2003 a 2010. Las 60 preguntas interactivas se seleccionaron de 2005-1 y sus respuestas se contrastaron con la hoja de claves incluida. Estos materiales no representan por sí solos el currículo ni el formato actual del examen. Consulta también la <a href="https://www.icfes.gov.co/caja-de-herramientas-saber-11/practica/" target="_blank" rel="noopener">práctica oficial del ICFES</a>.</p></div></div><div class="source-cards"><article class="source-card">${icon('bank',22)}<h3>La colección que compartiste</h3><p>106 archivos PDF organizados por periodo y asignatura. Conservamos los cuadernillos originales para consultar sus diagramas, textos e instrucciones.</p><a href="#archive-list">Explorar la colección ${icon('arrow',12)}</a></article><article class="source-card">${icon('shield',22)}<h3>Claves contrastadas</h3><p>Las respuestas interactivas proceden de la hoja de claves de 2005-1. Los ítems de matemáticas tipo X aceptan las dos opciones registradas en esa fuente.</p><a href="archive/2005-1/respuestas.xls" download>Consultar hoja de claves ${icon('download',12)}</a></article><article class="source-card">${icon('external',22)}<h3>Material oficial para seguir</h3><p>Accede a los recursos publicados por el ICFES para familiarizarte con Saber 11 y complementar el trabajo con esta colección histórica.</p><a href="https://www.icfes.gov.co/caja-de-herramientas-saber-11/practica/" target="_blank" rel="noopener">Ir a la Caja de Herramientas ${icon('external',12)}</a></article></div><section id="archive-list"><div class="section-heading"><div><h2>Tu biblioteca de consulta</h2><p>Los archivos se abren en su formato original.</p></div><span class="pill">2003–2010</span></div><div class="tool-row"><div class="search-field">${icon('search',17)}<input id="source-search" type="search" placeholder="Buscar por asignatura o profundización…" value="${esc(sourceFilter.search)}" aria-label="Buscar cuadernillos"></div><select id="source-period" aria-label="Filtrar por periodo"><option value="all">Todos los periodos</option>${periods.map(p=>`<option value="${p}" ${sourceFilter.period===p?'selected':''}>${p}</option>`).join('')}</select></div><div id="source-results">${sourceResults()}</div></section><div class="method-note"><h3>Sobre la selección y las explicaciones</h3><p>Se normalizaron espacios, tildes y algunos enunciados para facilitar la lectura en pantalla. Se mantienen la numeración, el sentido de las alternativas y su correspondencia con las claves. Los diagramas de piscina se redibujaron a partir de las medidas originales. Puedes contrastar cada adaptación con el PDF enlazado.</p><p>Las explicaciones son orientaciones didácticas elaboradas para Punto, no explicaciones oficiales del ICFES. El ítem 16 de Matemáticas, retirado de calificación en el documento, no se incorporó al banco. Tampoco se incluyeron los ítems 15 de Matemáticas y 8 de Lenguaje, que requieren revisión adicional de su formulación o correspondencia con la clave.</p><p>La colección se incorporó a partir del material aportado para este proyecto educativo y conserva las atribuciones de origen. Punto es una plataforma independiente, sin afiliación con el ICFES.</p></div>`;}
function sourceResults(){const list=catalog.filter(p=>(sourceFilter.period==='all'||p.period===sourceFilter.period)&&normalize(`${p.title} ${p.period}`).includes(normalize(sourceFilter.search)));const pages=Math.max(1,Math.ceil(list.length/12));sourceFilter.page=Math.min(sourceFilter.page,pages);return `<div class="bank-meta"><span>${list.length} documentos encontrados</span><span>PDF original</span></div>${list.length?list.slice((sourceFilter.page-1)*12,sourceFilter.page*12).map(p=>`<article class="pdf-row"><div class="pdf-icon">PDF</div><div><h3>${esc(p.title)}</h3><p>${p.period} · ${(p.bytes/1024/1024).toFixed(1)} MB</p></div><a href="${encodeURI(p.url)}" target="_blank" rel="noopener">Abrir ${icon('external',13)}</a></article>`).join(''):'<div class="empty-state"><h2>No hay cuadernillos con esa búsqueda.</h2><p>Prueba otra asignatura o periodo.</p></div>'}${pagination(sourceFilter.page,pages,'source')}`;}
function render(scroll=true){let target=location.hash.slice(1)||'inicio';route=['inicio','banco','guardadas','simulacro','progreso','practica','resultados','fuentes'].includes(target)?target:target==='archive-list'?'fuentes':'inicio';nav();const views={inicio:home,banco:bankView,guardadas:bankView,simulacro:examView,practica:practiceView,progreso:progressView,resultados:resultView,fuentes:sourcesView};$('#main').innerHTML=views[route]();if(!storageOK&&!$('#storage-warning'))$('#main').insertAdjacentHTML('afterbegin','<div class="inline-error" id="storage-warning">El guardado local no está disponible. Conserva una copia usando Exportar progreso.</div>');document.title=`${$('#crumb').textContent} · Punto`;if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}if(target==='archive-list')$('#archive-list')?.scrollIntoView({behavior:'smooth'});}
function previewQuestion(id){const q=getQuestion(id);if(!q)return;const a=areaBy(q.area);showModal('Una pregunta, un nuevo paso.',`<article class="question-card"><div class="question-kicker"><span class="pill" style="background:${a.light};color:${a.color}">${a.name}</span><span class="pill">2005-1 · N.º ${q.number}</span></div><h1>${esc(q.title)}</h1>${contextMarkup(q)}<p class="prompt" ${q.area==='ingles'?'lang="en"':''}>${esc(q.prompt)}</p><div style="font-size:11px;color:#8a9bb2">${q.answers.length>1?'Ítem histórico con dos alternativas aceptadas.':'Selección de respuesta.'} Practica esta pregunta para ver las opciones y comprobar tu respuesta.</div>${sourceMarkup(q)}</article><div class="modal-actions">${btn(state.bookmarks.includes(q.id)?'Guardada':'Guardar pregunta','bookmark','secondary',`data-id="${id}"`,'bookmark')}${btn('Resolver esta pregunta','single-question','primary',`data-id="${id}"`)}</div>`,{wide:true});}
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(r){const rows=[['Punto - Resultado de práctica',''],['Fecha',new Date(r.finishedAt).toISOString()],['Modo',r.mode==='exam'?'Simulación':'Práctica'],['Aciertos',r.summary.percentage+'%'],['Nota','Porcentaje de práctica, no puntaje oficial del ICFES'],[],['Pregunta','Área','Título','Tu respuesta','Clave','Correcta','Fuente','Explicación']];for(const id of r.ids){let q=getQuestion(id);rows.push([q.number,areaBy(q.area).name,q.title,r.answers[id]||'Omitida',q.answers.join(' / '),isCorrect(q,r.answers[id])?'Sí':'No',`2005-1/${q.discipline} p.${q.page}`,q.explanation]);}const csv='\uFEFF'+rows.map(row=>row.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));let a=document.createElement('a');a.href=url;a.download=`Punto-resultado-${new Date(r.finishedAt).toISOString().slice(0,10)}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateImport(data){if(!data||data.application!=='punto'||data.version!==1||!data.progress)throw Error('Ese archivo no es una exportación de Punto compatible.');const p=data.progress;if(!Array.isArray(p.bookmarks)||!Array.isArray(p.history)||!p.attempts||typeof p.attempts!=='object'||Array.isArray(p.attempts))throw Error('El archivo no contiene un progreso válido.');const clean={version:1,bookmarks:[...new Set(p.bookmarks.filter(id=>getQuestion(id)))],attempts:{},history:[],session:null,reports:[]};for(const [id,entries] of Object.entries(p.attempts)){if(!getQuestion(id)||!Array.isArray(entries))continue;clean.attempts[id]=entries.filter(a=>a&&LETTERS.includes(a.answer)&&Number.isFinite(a.at)&&typeof a.sessionId==='string').slice(-100).map(a=>({answer:a.answer,correct:isCorrect(getQuestion(id),a.answer),at:a.at,sessionId:a.sessionId}));}for(const h of p.history.slice(0,200)){if(!h||typeof h.id!=='string'||!Array.isArray(h.ids)||!h.ids.length||h.ids.length>60||!h.ids.every(getQuestion)||!h.answers||typeof h.answers!=='object'||!Number.isFinite(h.finishedAt)||!Number.isFinite(h.startedAt)||!Number.isFinite(h.duration))continue;const ids=[...new Set(h.ids)],answers={};for(const id of ids)if(LETTERS.includes(h.answers[id]))answers[id]=h.answers[id];clean.history.push({id:h.id,ids,answers,mode:h.mode==='exam'?'exam':'learn',area:areaBy(h.area)?h.area:'all',startedAt:h.startedAt,finishedAt:h.finishedAt,duration:Math.max(0,h.duration),expired:!!h.expired,summary:evaluate(ids.map(getQuestion),answers)});}return clean;}
let importCandidate=null;
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(state.session?.mode==='exam'&&remainingSeconds(state.session)<=0){finishSession(true);return;}const a=el.dataset.action,id=el.dataset.id,s=state.session;
 switch(a){case 'quick':practiceConfig();break;case 'area-practice':practiceConfig(el.dataset.area);break;case 'resume':closeModal();navigate('practica');break;case 'close-modal':closeModal();break;case 'go-bank':closeModal();navigate('banco');break;case 'go-progress':navigate('progreso');break;case 'session-home':navigate('inicio');toast(s?.mode==='exam'?'Tu simulación continúa y el reloj sigue corriendo.':'Tu práctica está guardada. Puedes continuarla cuando quieras.');break;
 case 'info':showModal('Tu propio punto de partida.',`<p>Punto es un espacio para entrenar con preguntas históricas, aprender de las respuestas y construir una rutina de estudio.</p><div class="config-note">No necesitas crear una cuenta. Tu progreso se guarda en este navegador y puedes exportarlo en Mi progreso. Este espacio forma parte de los recursos educativos de Tech-GLM.</div><p>El material interactivo es de 2005. Consulta Biblioteca para ver su procedencia y acceder a los recursos oficiales actuales.</p><div class="modal-actions">${btn('Entendido','close-modal','primary','',null)}</div>`);break;
 case 'filter-status':filter.status=el.dataset.status;filter.page=1;render(false);break;case 'reset-filters':filter={search:'',area:'all',status:'all',page:1};render(false);break;case 'filtered-practice':practiceConfig(filter.area,matchingQuestions().map(q=>q.id));break;case 'preview-question':previewQuestion(id);break;case 'bank-page':filter.page=+el.dataset.page;$('#bank-results').innerHTML=bankResults();$('.tool-row')?.scrollIntoView({behavior:'smooth'});break;case 'source-page':sourceFilter.page=+el.dataset.page;$('#source-results').innerHTML=sourceResults();$('#archive-list').scrollIntoView({behavior:'smooth'});break;
 case 'bookmark':{state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];persist();const saved=state.bookmarks.includes(id);toast(saved?'Pregunta guardada para volver después.':'Pregunta quitada de tu colección.');if($('#modal').open){for(const b of document.querySelectorAll(`[data-action="bookmark"][data-id="${id}"]`)){b.classList.toggle('saved',saved);if(b.classList.contains('btn'))b.innerHTML=(saved?'Guardada':'Guardar pregunta')+icon('bookmark',14);else{b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',saved?'Quitar de guardadas':'Guardar pregunta');}}}else if(route==='banco'||route==='guardadas')$('#bank-results').innerHTML=bankResults();else render(false);break;}
 case 'single-question':closeModal();requestStart({ids:[id],count:1,mode:'learn'});break;case 'replace-session':{const c=pendingConfig;pendingConfig=null;finishSession();if(c)startSession(c);break;}
 case 'start-exam':requestStart({...examConfig,mode:'exam'});break;case 'answer':if(s){const q=getQuestion(s.ids[s.index]);if(s.mode==='learn'&&s.checked[q.id])break;s.answers[q.id]=el.dataset.letter;persist();const top=window.scrollY;render(false);window.scrollTo(0,top);document.querySelector(`[data-action="answer"][data-letter="${el.dataset.letter}"]`)?.focus({preventScroll:true});}break;case 'check-answer':checkAnswer();break;
 case 'prev-question':if(s){s.index=Math.max(0,s.index-1);persist();render();}break;case 'next-question':if(s){if(s.index<s.ids.length-1){s.index++;persist();render();}else requestFinish();}break;case 'goto-question':if(s){s.index=Number(el.dataset.index);persist();render();}break;case 'finish-session':requestFinish();break;case 'confirm-finish':finishSession();break;
 case 'open-result':lastResultId=id;reviewFilter='all';navigate('resultados');break;case 'review-filter':reviewFilter=el.dataset.filter;render(false);break;case 'retry-errors':{const r=getResult();const ids=r.ids.filter(id=>!isCorrect(getQuestion(id),r.answers[id]));practiceConfig('all',ids);break;}
 case 'practice-pending':practiceConfig('all',questions.filter(q=>questionStatus(q,state)==='review').map(q=>q.id));break;case 'export-result':exportCSV(getResult());break;case 'export-progress':downloadJSON({application:'punto',version:1,exportedAt:new Date().toISOString(),progress:{...state,session:null}},'Punto-mi-progreso.json');toast('Progreso exportado. Guárdalo para conservar tu historial.');break;
 case 'import-progress':$('#progress-file')?.click();break;case 'confirm-import':if(importCandidate){state=importCandidate;importCandidate=null;lastResultId=null;persist();closeModal();render();toast('Progreso importado. Ya puedes continuar.');}break;
 case 'reset-data':showModal('¿Borrar tu progreso de este navegador?',`<p>Se eliminarán tus respuestas, sesiones y preguntas guardadas. Exporta una copia antes de continuar si quieres conservarlas.</p><div class="modal-actions">${btn('Cancelar','close-modal','secondary','',null)}${btn('Borrar mis datos','confirm-reset','danger','',null)}</div>`);break;case 'confirm-reset':state={version:1,bookmarks:[],attempts:{},history:[],session:null,reports:[]};lastResultId=null;persist();closeModal();render();toast('Tus datos se borraron de este navegador.');break;
 case 'report':showModal('Anota algo para revisar.',`<p>Pregunta ${getQuestion(id).number} · ${esc(getQuestion(id).title)}. Tu nota se guardará en tu copia de progreso; puedes descargarla para compartirla con tu docente.</p><form id="report-form"><input type="hidden" name="id" value="${id}"><label class="report-label" for="report-text">¿Qué encontraste?</label><textarea class="report-input" id="report-text" name="text" required maxlength="1500" placeholder="Describe la duda, una errata o la parte que conviene revisar…"></textarea><div class="modal-actions">${btn('Cancelar','close-modal','secondary','',null)}<button class="btn btn-primary" type="submit">Guardar y descargar nota ${icon('download',14)}</button></div></form>`);break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='bank-search'){filter.search=e.target.value;filter.page=1;$('#bank-results').innerHTML=bankResults();}if(e.target.id==='source-search'){sourceFilter.search=e.target.value;sourceFilter.page=1;$('#source-results').innerHTML=sourceResults();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='bank-area'){filter.area=el.value;filter.page=1;$('#bank-results').innerHTML=bankResults();}if(el.id==='source-period'){sourceFilter.period=el.value;sourceFilter.page=1;$('#source-results').innerHTML=sourceResults();}if(el.id==='exam-area'){examConfig.area=el.value;const max=questions.filter(q=>el.value==='all'||q.area===el.value).length;examConfig.count=Math.min(examConfig.count,Math.floor(max/10)*10||max);render(false);}if(el.name==='exam-count'){examConfig.count=Number(el.value);examConfig.minutes=Number(el.value)*2;render(false);}if(el.id==='exam-minutes')examConfig.minutes=Number(el.value);if(el.id==='progress-file'&&el.files[0]){try{if(el.files[0].size>5*1024*1024)throw Error('El archivo supera el tamaño permitido de 5 MB.');importCandidate=validateImport(JSON.parse(await el.files[0].text()));showModal('¿Cargar esta copia de progreso?',`<p>La copia contiene ${importCandidate.history.length} sesiones y ${importCandidate.bookmarks.length} preguntas guardadas. Reemplazará el progreso de este navegador. Exporta primero tus datos actuales si quieres conservarlos.</p><div class="modal-actions">${btn('Cancelar','close-modal','secondary','',null)}${btn('Importar esta copia','confirm-import','primary','',null)}</div>`);}catch(error){toast(error.message||'No se pudo leer el archivo.');}el.value='';}});
document.addEventListener('submit',e=>{if(e.target.id==='practice-form'){e.preventDefault();const data=new FormData(e.target);requestStart({area:data.get('area'),count:Number(data.get('count')),mode:'learn',ids:data.get('ids')?JSON.parse(data.get('ids')):null});}if(e.target.id==='report-form'){e.preventDefault();const data=new FormData(e.target),q=getQuestion(data.get('id'));const report={questionId:q.id,number:q.number,title:q.title,note:String(data.get('text')).trim(),createdAt:new Date().toISOString()};if(!report.note)return;state.reports.push(report);persist();downloadJSON(report,`Punto-nota-pregunta-${q.number}.json`);closeModal();toast('Tu nota quedó guardada y descargada.');}});
document.addEventListener('keydown',e=>{if(route!=='practica'||$('#modal').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(['1','2','3','4'].includes(e.key)){const button=$(`[data-action="answer"][data-letter="${LETTERS[+e.key-1]}"]`);if(button&&!button.disabled){e.preventDefault();button.click();}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(bank)render();});
setInterval(()=>{if(!bank||!validSession(state.session))return;const s=state.session;const timer=$('#session-timer');if(s.mode==='exam'){const left=remainingSeconds(s);if(left<=0){finishSession(true);return;}if(timer){$('span',timer).textContent=formatTime(left);timer.classList.toggle('urgent',left<=60);}}else if(timer)$('span',timer).textContent=formatTime((Date.now()-s.startedAt)/1000);},500);
async function init(){try{const response=await fetch('./bank.json');if(!response.ok)throw Error('No se pudo cargar el banco de preguntas.');bank=await response.json();questions=bank.questions;catalog=bank.catalog;if(state.session&&!validSession(state.session)){state.session=null;persist();}$('#date-label').textContent=dateFmt(Date.now(),{day:'numeric',month:'long'});if(state.session?.mode==='exam'&&remainingSeconds(state.session)===0){finishSession(true);}else render();}catch(error){$('#main').innerHTML=`<div class="empty-state"><h2>No pudimos abrir tu banco de preguntas.</h2><p>Comprueba tu conexión y vuelve a cargar esta página.</p><button class="btn btn-primary" id="reload">Volver a cargar</button></div>`;$('#reload').addEventListener('click',()=>location.reload());console.error(error);}}
init();
